from research_helpers import Batch
b=Batch(33)
b.add('Malvi','lightning','bij|vij','11742','CDIAL 11742 vidyut gives Prakrit vijju, Punjabi bijj, Old Awadhi bīju and Gujarati/Marathi vīj ‘lightning’. The bare j-final forms fit this family without the -l- member of vidyullatā (11745); a contraction of the latter cannot be excluded from surface form alone, so the branch choice remains qualified.',tier='qualified')
b.add('Malvi','gold','hono|honːo|honā|huṇa|hunːo','13519','CDIAL 13519 lists Prakrit soṇṇa, Hindi sonā, Gujarati sɔnũ and western sun(n)-forms, but explicitly says suvarṇa and sauvarṇa cannot generally be separated in NIA. Malvi h- is supported by independent same-survey s/h correspondences at Chandukhedi, Bhunyakhedi, Jesingpura and Jamli (MALVI-S-H.md); vowel/nasal/gemination variation and the two historical bases remain qualified.',tier='qualified',locator='13519, 1 or 2')
b.add('Malvi','snake','hāp|hap','13271','CDIAL 13271 sarpa gives Prakrit sappa and western Hindi/Gujarati/Marathi sāp. The same survey independently shows s/h correspondences in dry, seven, hundred and hear at Chandukhedi, Bhunyakhedi, Jesingpura and Jamli, where these snake forms also occur (MALVI-S-H.md); vowel length variation is retained and this is not a claim that every Malvi lect changes s to h.',tier='qualified')
b.add('Malvi','snake','ā̃p','13271','The nasalized snake form compares with Hindi/Maithili sā̃p under CDIAL 13271, with additional initial loss. The regional survey has hāp/hap elsewhere, while this exact Bhandia ā̃p record remains qualified for s/h loss and nasalization; Bhandia is not claimed to attest the hāp intermediary.',tier='qualified')
b.add('Malvi','needle','hui|ui','13551','CDIAL 13551.1 gives Prakrit sūī, Hindi sūī and Marathi sūī, with loss of medial c; it is not the *sūñcī branch retaining an affricate. Independent same-survey s/h correspondences support hui at Chandukhedi, Bhunyakhedi and Jamli, while Jesingpura ui has additional initial loss; vowel length and loss of h remain qualified (MALVI-S-H.md).',tier='qualified',locator='13551.1')
b.save()
